pub interface Printable {
  fn format(self: &Self) -> Str;
}

pub interface Loggable extends Printable {
  fn log_level(self: &Self) -> Str { return "INFO"; }

  fn log(self: &Self) {
    io.println("[" + self.log_level() + "] " + self.format());
  }
}

pub type Event = { name: Str; }

impl Printable for Event {
  fn format(self: &Event) -> Str { return "Event: " + self.name; }
}

impl Loggable for Event {
  fn log_level(self: &Event) -> Str { return "EVENT"; }
}

fn main() -> Int {
  let e = Event{ name: "startup" };
  e.log();
  return e.name.len();
}
